function svg(body,h=220){return `<svg viewBox="0 0 700 ${h}" xmlns="http://www.w3.org/2000/svg" role="img"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#167f86"/></marker></defs><style>text{font:15px Tahoma;fill:#163349}.wire{fill:none;stroke:#167f86;stroke-width:3}.hv{stroke:#e27529}.box{fill:#edf7f7;stroke:#167f86;stroke-width:2}.thin{fill:none;stroke:#607887;stroke-width:2}</style>${body}</svg>`}
const box=(x,y,w,h,a,b='')=>`<rect class="box" x="${x}" y="${y}" width="${w}" height="${h}" rx="7"/><text x="${x+w/2}" y="${y+h/2- (b?4:-5)}" text-anchor="middle">${esc(a)}</text>${b?`<text x="${x+w/2}" y="${y+h/2+19}" text-anchor="middle" style="font-size:12px">${esc(b)}</text>`:''}`;
const wire=(d,hv=false)=>`<path d="${d}" class="wire ${hv?'hv':''}"/>`;
function flow(labels){let w=620/labels.length;return svg(labels.map((t,i)=>box(20+i*(w+12),65,w-12,75,...t.split('|'))+(i<labels.length-1?`<path d="M${20+i*(w+12)+w-12} 103 h24" class="wire" marker-end="url(#arrow)"/>`:'')).join('')+'<text x="350" y="190" text-anchor="middle" style="font-size:12px">FUNCTIONAL FLOW • no vehicle-specific terminals</text>');}
