function fig(key,caption,source='ผู้จัดทำ • วาดใหม่จากหลักการทั่วไป'){return `<figure class="visual">${circuits[key]?circuits[key]():flow(key)}<figcaption><b>B · Simplified Circuit Diagram</b> — ${caption}<br>แหล่งภาพ: ${source} • ภาพวาดใหม่เพื่อการศึกษา ไม่ใช่ผังสายไฟเฉพาะรุ่น • สิทธิ์ภาพใหม่: CC BY 4.0</figcaption></figure>`;}
