add('01 / เริ่มต้น','สารบัญและทางลัดใช้งาน','จำนวนหน้าเป็นส่วนหนึ่งของโครงสร้างเล่ม',table(['บท','หน้า','เปิดเมื่อพบอาการ'],[
 ['ปก / สารบัญ / วิธีใช้','1–3','เริ่มอ่านและกำหนดขอบเขตงาน'],['โครงสร้างวงจร EV','4–8','รถไม่ READY / แยก HV กับ LV'],['ECU / VCU','9–14','กล่องไม่ตื่น / ไฟเลี้ยง / Input–Output'],['BMS','15–20','Cell / อุณหภูมิ / กระแส / Contactor'],['Inverter / Motor','21–25','ไม่ขับเคลื่อน / Feedback / Gate driver'],['OBC / DC-DC / Charging','26–30','ชาร์จไม่เข้า / ไฟ LV ไม่ขึ้น'],['CAN Bus','31–35','กล่องหาย / U-code / รูปคลื่น'],['ตารางและแนวทาง DTC','36–44','ฉนวน / แบตเตอรี่ / ชาร์จ / หลังน้ำท่วม'],['กรณีศึกษา','45–48','ตัวอย่างตัดสินใจจากหลักฐาน'],['ตารางอ้างอิง / แหล่งข้อมูล','49–50','ทบทวนค่าตัวอย่างและสิทธิ์ภาพ']])+note('ลัดตามอาการ: ไม่ READY → 8, 9, 20, 35 · ชาร์จไม่เข้า → 26–30, 40 · หลังน้ำท่วม → 7, 37, 43–44, 48')+table(['สัญลักษณ์ภาพ','ความหมาย'],[['A · Actual Wiring Diagram','วงจรจริงของบอร์ด/ระบบที่ระบุแหล่งและสิทธิ์ ไม่ได้หมายถึงผังรถทุกรุ่น'],['B · Simplified Circuit Diagram','ภาพวาดใหม่เพื่ออธิบายหลักการ ห้ามใช้ระบุขาหรือสีสายรถ'],['C · Actual Component Photograph','ภาพถ่ายชิ้นงานจริงพร้อมเครดิต ไม่ใช่ภาพ AI']]) );
add('01 / เริ่มต้น','ใช้คู่มืออย่างไรให้ตรวจงานได้','เริ่มจากอาการและข้อมูลรถ ก่อนเริ่มวัด',steps(['คัดกรองอุบัติเหตุ/น้ำท่วมและอาการอันตรายก่อนต่อเครื่องสแกนหรือปลุกระบบ หากไม่ปลอดภัยให้หยุดและส่งผู้ชำนาญ','ระบุ VIN (เลขตัวรถ) รุ่น ปี และคู่มือบริการตรงรถ แยกงานแรงดันต่ำ LV (Low Voltage) กับแรงดันสูง HV (High Voltage)','เมื่อผ่านการประเมินและขั้นตอน OEM ให้อ่านทุกกล่อง เก็บ DTC (Diagnostic Trouble Code: รหัสข้อผิดพลาด), รหัสย่อย และ Freeze frame (ข้อมูลขณะเกิดเหตุ) ก่อนลบ','เลือกจุดวัดจากผังที่ยืนยันแล้ว ซ่อมสาเหตุ และทวนสอบตามเงื่อนไขเดิม'])+table(['คำย่อครั้งแรก','ความหมายในเล่ม'],[['EV / HEV / PHEV','รถไฟฟ้าแบตเตอรี่ / ไฮบริด / ไฮบริดเสียบปลั๊ก'],['ECU / VCU','กล่องควบคุมอิเล็กทรอนิกส์ / กล่องควบคุมการทำงานรถ'],['BMS / OBC','ระบบจัดการแบตเตอรี่ / เครื่องชาร์จที่ติดตั้งในรถ'],['CAN / DC-DC','เครือข่ายสื่อสารของกล่อง / ตัวแปลงไฟตรงเป็นไฟตรง'],['OEM / TSB','ผู้ผลิตรถ / เอกสารบริการทางเทคนิค']])+note('งาน HV ต้องมีผู้ผ่านการฝึกเฉพาะงาน ใช้ขั้นตอนแยกและล็อกแหล่งพลังงานของผู้ผลิต แล้วพิสูจน์ว่าไม่มีแรงดัน ณ จุดทำงานด้วยเครื่องมือที่เหมาะสม ทวนสอบเครื่องตรวจแรงดันกับ proving unit/แหล่งที่เหมาะสมก่อนและหลังตรวจตาม OEM; เครื่องตรวจแบบไม่สัมผัสใช้รับรองปลอดไฟไม่ได้ การดับรถหรือถอด 12 V ไม่รับรองว่า HV ปลอดภัย',true)+field(),['S1']);

add('02 / โครงสร้าง EV','แผนที่ระบบ: พลังงานกับข้อมูล','อ่านว่าพลังงานไปทางไหน และใครสั่งให้ทำงาน',fig('architecture','ภาพรวมแบตเตอรี่ ชุดขับเคลื่อน และไฟเลี้ยงควบคุม')+checks([['แบตเตอรี่ HV → Inverter','อ่านแรงดันแพ็ก/บัสจากสแกน','มีแรงดันแพ็กไม่เท่ากับคอนแทกเตอร์ปิด'],['DC-DC → แบตเตอรี่ LV','เทียบแรงดันขณะพักกับโหมดทำงานที่ OEM ระบุ','ยืนยันคำสั่ง Enable ก่อนตัดสินตัวแปลงเสีย'],['VCU ↔ BMS / Inverter','ดูสถานะอนุญาตแรงบิดและ READY','รหัสต้นเหตุในกล่องหนึ่งอาจทำให้หลายระบบหยุด'],['การเบรกคืนพลังงาน','ดู SOC อุณหภูมิและคำสั่งจำกัดพลังงาน','การคืนพลังงานต่ำอาจเป็นข้อจำกัดปกติ']])+note('SOC (State of Charge) คือระดับประจุ ส่วนแรงดันที่เห็นเป็นเพียงหนึ่งข้อมูล ไม่ใช่ผลทดสอบสุขภาพแบตเตอรี่ทั้งหมด'));
add('02 / โครงสร้าง EV','แยกฝั่ง HV และ LV ก่อนวัด','สีส้มเป็นสิ่งเตือน ไม่ใช่หลักฐานว่าจุดอื่นปลอดภัย',table(['ระบบ','ตัวอย่างหน้าที่','วิธีเริ่มตรวจ'],[['LV','แบตเตอรี่ช่วย กล่องควบคุม รีเลย์ เซนเซอร์','เริ่มจากผังฟิวส์และกราวด์ตรงรุ่น'],['HV','แบตเตอรี่ขับเคลื่อน OBC Inverter คอมเพรสเซอร์ไฟฟ้า','ใช้ผู้มีคุณสมบัติและขั้นตอน OEM'],['HV ที่ถูกแยก','ตัวเก็บประจุ DC-link / ส่วนภายในแพ็ก','ยังอาจมีพลังงานสะสม ห้ามถือว่าไม่มีไฟ'],['สัญญาณข้ามเขต','CAN แบบแยกวงจร / Isolated gate driver','ตรวจขอบเขตการแยกไฟก่อนต่อเครื่องมือ']])+fig(['รับรถ|ประวัติ/ภาพถ่าย','ประเมินเสี่ยง|HV / น้ำท่วม','ข้อมูล OEM|VIN / ผัง','เลือกงาน|LV / ผู้ชำนาญ'],'กระบวนการกำหนดขอบเขตก่อนวัด')+note('ห้ามใช้ออสซิลโลสโคปตั้งโต๊ะที่กราวด์ผูกสายดินแตะวงจร HV โดยตรง ห้ามยกเลิกสายดินเพื่อแก้ปัญหา ใช้ชุดวัดและโพรบที่มีพิกัดตรงงาน',true),['S1']);
add('02 / โครงสร้าง EV','อ่านผังสายไฟและยืนยันหัวต่อ','มุมมอง Connector คือจุดที่ทำให้สลับขาได้ง่าย',slot('A','ผังไฟเลี้ยง VCU และ Connector view ตาม VIN พร้อมเลขเอกสาร OEM')+table(['ข้อมูลที่ต้องตรง','ตรวจจากอะไร','ผิดแล้วเกิดอะไร'],[['รุ่น / ปี / option','VIN และรหัสอุปกรณ์','ใช้ผังคนละระบบ'],['Connector view','ด้านขั้ว / ด้านสาย และตำแหน่งสลัก','นับขากลับด้าน'],['หมายเลขขา / cavity','สัญลักษณ์หัวต่อและรหัสสาย','วัดผิดขา เสี่ยงลัดวงจร'],['จุดต่อร่วม / splice','เส้นอ้างอิงหน้าและกราวด์','พลาดจุดเสียร่วมหลายกล่อง'],['ฉบับปรับปรุง','วันที่ เอกสาร และการแก้ไข','ใช้ pinout ที่ยกเลิกแล้ว']])+steps(['ถ่ายภาพสลักและหมายเลขหัวต่อจริง เทียบเอกสารโดยไม่เดาขา','ทำแผ่นงาน: ชื่อขา หน้าที่ แหล่งอ้างอิง สภาพรถ ค่าคาดหมาย','ใช้สายทดสอบหรือ breakout ที่เหมาะสม ไม่แทงสายหรือทำให้ซีลเสีย'])+note('หนังสือนี้ไม่กำหนด pinout ของรถที่ไม่มีเอกสารยืนยัน เลขขาในวงจรบอร์ดตัวอย่างใช้ได้เฉพาะบอร์ดนั้น'));
add('02 / โครงสร้าง EV','คัดกรองรถหลังน้ำท่วม','มีน้ำเข้ารถ ≠ อนุญาตให้ทดลองเปิดระบบ',fig(['รับประวัติน้ำ|ระดับ/ชนิด/เวลา','มีอาการเสี่ยง?|ร้อน/ควัน/เสียง','กั้นพื้นที่|ผู้ตอบเหตุ','ตรวจเฉพาะงาน|ตาม OEM'],'จุดตัดสินใจรับรถน้ำท่วม; พบอาการอันตรายให้หยุดและออกห่าง')+checks([['แพ็กจมน้ำ / กระแทก / น้ำเค็ม','บันทึกจากระยะปลอดภัย แจ้งผู้เชี่ยวชาญ','ไม่สตาร์ต ไม่ชาร์จ ไม่เปิดแพ็กเพื่อทดลอง'],['ร้อนผิดปกติ ควัน กลิ่นฉุน เสียงฟู่','หยุดงาน ออกจากพื้นที่ ติดต่อหน่วยฉุกเฉิน','ไม่รอผล DTC เพื่อยืนยันอันตราย'],['รถแห้งแล้วแต่มีคราบเกลือ','ถือว่ายังมีความเสี่ยงสะพานนำไฟ','การแห้งไม่รับรองความปลอดภัย'],['ไม่มี DTC / สแกนไม่ได้','บันทึกสถานะและข้อจำกัด','ไม่ใช่หลักฐานว่าแพ็กปลอดภัย']])+note('จัดเก็บและกู้รถตามแผนของสถานที่และคู่มือฉุกเฉินเฉพาะรุ่น ให้หน่วยกู้ที่มีความพร้อมเคลื่อนย้าย ไม่ทดลองขับเพื่อตรวจอาการ',true),['S8','S9','S15']);
add('02 / โครงสร้าง EV','ลำดับตรวจรถไม่ READY','READY คือสถานะพร้อมขับ ไม่ใช่เพียงหน้าจอติด',fig(['LV พร้อม?|ไฟ/กราวด์','กล่องตื่น?|สื่อสาร','เงื่อนไขผ่าน?|เบรก/เกียร์/HVIL','HV พร้อม?|precharge','READY|ยืนยันสถานะ'],'ลำดับตรวจเชิงหน้าที่ ไม่ใช่ขั้นตอนปิดคอนแทกเตอร์ด้วยตนเอง')+checks([['จอไม่ติด / สแกนไม่ได้','ตรวจแบตเตอรี่ LV ฟิวส์ กราวด์','เริ่มจุดร่วมก่อนแยกหลายกล่อง'],['จอติดแต่ไม่ READY','อ่านกล่องทั้งหมดและสถานะอนุญาต','แยกไม่รับคำขอ กับรับแต่ไม่อนุญาต'],['มีเสียงรีเลย์แล้วตัด','อ่านเวลาเกิดเหตุ แรงดันบัส และ DTC','เสียงคลิกไม่ยืนยันว่าหน้าสัมผัสดี'],['เกิดหลังฝนหรือน้ำท่วม','ตรวจประวัติกับเกณฑ์หน้า 7','ผ่านการประเมินก่อนจ่ายไฟ']])+note('HVIL (High Voltage Interlock Loop) คือวงจรตรวจความครบของหัวต่อ/ฝาครอบ HV ห้ามจัมป์เพื่อบังคับ READY'));

add('03 / ECU และ VCU','ไฟเลี้ยง 12 V: ตรวจที่ต้นทางและปลายทาง','รถบางรุ่นใช้ระบบ LV ต่างจาก 12 V ต้องดูข้อมูลรถ',fig('vcu','เส้นทางไฟเลี้ยง VCU แบบย่อ ไม่มีเลขขาหรือสีสาย')+checks([['ขั้วแบตเตอรี่ LV','วัดขณะพักและขณะปลุกระบบ','เทียบชนิดแบตเตอรี่และข้อกำหนด OEM'],['ฟิวส์และจุดต่อ','ตรวจแรงดันทั้งสองด้านเมื่อมีโหลด','ดูด้วยตาอย่างเดียวพลาดหน้าสัมผัสต้านทานสูง'],['ขาไฟเลี้ยงกล่อง','ยืนยันขาจากผัง วัดสภาพที่เกิดอาการ','แบตเตอรี่ดีแต่ไฟถึงกล่องตก → ไล่สาย'],['รางไฟภายใน PCB','เฉพาะบอร์ดแยกจากรถและมีผังยืนยัน','ไม่มี 5 V อาจเกิดจากโหลดชอร์ต ไม่ใช่ IC เสียเสมอ']])+steps(['บันทึกแรงดันแบตเตอรี่พร้อมเวลาเกิดอาการ','เทียบแรงดันที่กล่องกับแบตเตอรี่ในสภาพโหลดเดียวกัน','แก้ขั้วหลวมหรือการตกคร่อม แล้วสแกนซ้ำก่อนเปลี่ยนกล่อง']));
add('03 / ECU และ VCU','Ground และ Ignition / Wake','กราวด์อ่านต่อถึงกันได้ แต่รับโหลดไม่ไหวก็มีได้',fig('vcu','ตรวจทางจ่ายและทางกลับด้วย voltage drop')+table(['ทดสอบ','การต่อมิเตอร์ฝั่ง LV','ข้อจำกัด'],[['Voltage drop กราวด์','ขากราวด์กล่องที่ยืนยันแล้ว ↔ ขั้วลบแบตเตอรี่ ขณะโหลดทำงาน','ใช้เกณฑ์ OEM และกระแสโหลด ไม่ตั้งค่าตัดสินครอบจักรวาล'],['Voltage drop สายบวก','ขั้วบวกแบตเตอรี่ ↔ ขาไฟกล่อง ขณะโหลดเดียวกัน','อ่านสูงให้แยกวัดทีละช่วง'],['IGN / Wake','ดูสัญญาณขณะปิด–เปิดตามแผนผัง','อาจเป็นสัญญาณดิจิทัลหรือข้อความ CAN'],['Continuity','วัดเมื่อปลอดไฟและแยกวงจรตาม OEM','เสียงบี๊บไม่ยืนยันความสามารถรับกระแส']])+note('ห้ามใช้หลอดทดสอบกระแสสูงกับขาสัญญาณหรือเครือข่าย การใส่โหลดจำลองต้องรู้พิกัดขาและได้รับอนุญาตจากขั้นตอนบริการ'));
add('03 / ECU และ VCU','Input: แรงดันอ้างอิงและสัญญาณเซนเซอร์','แยกสายจ่าย สายสัญญาณ และกราวด์เซนเซอร์',fig('input','เซนเซอร์แอนะล็อกสามสาย; ค่า 5 V เป็นตัวอย่างทั่วไป')+checks([['สัญญาณหลายตัวผิดพร้อมกัน','เทียบ reference rail และกราวด์ร่วม','โหลดเดียวอาจดึงไฟอ้างอิงทั้งกลุ่มลง'],['สัญญาณค้างต่ำ/สูง','ตรวจแรงดันที่เซนเซอร์และขากล่อง','ใช้เกณฑ์จริง ไม่สรุปว่าเซนเซอร์เสียทันที'],['แป้นคันเร่งสองช่อง','อ่านช่อง A/B และความสัมพันธ์ตาม OEM','ไม่สมมติว่าทั้งสองช่องเท่ากันหรือบวกกันคงที่'],['อาการเป็นครั้งคราว','บันทึกกราฟขณะเกิดเหตุโดยยึดสายวัดให้มั่นคง','ค่าเฉลี่ยมิเตอร์อาจไม่เห็นการขาดช่วง']])+note('ADC (Analog-to-Digital Converter) คือวงจรแปลงแรงดันเป็นข้อมูลดิจิทัล ห้ามป้อนไฟภายนอกเข้าขา Input เพื่อเดาค่าปกติ'));
add('03 / ECU และ VCU','Output: ตรวจคำสั่งก่อนตัดสินโหลด','มีคำสั่งกับมีพลังงานถึงโหลดเป็นคนละหลักฐาน',fig('output','ตัวอย่าง low-side driver; ไม่ใช่ทุกกล่องขับแบบนี้')+checks([['รีเลย์ไม่ทำงาน','ดูคำสั่ง สภาพอนุญาต และไฟถึงขดลวด','คำสั่ง OFF อาจเป็นการป้องกันปกติ'],['PWM ไปโหลด','สโคปที่จุด LV ที่ยืนยัน พร้อมกราวด์ถูกต้อง','PWM คือการควบคุมด้วยความกว้างพัลส์'],['ไฟถึงแต่ไม่ทำงาน','ตรวจความต้านทาน/กระแสตามสภาพปลอดไฟที่กำหนด','โหลดชอร์ตอาจทำ driver ป้องกันตัวเอง'],['เปิดแล้วตัดทันที','จับกราฟคำสั่งกับกระแสและ DTC','แยก overcurrent ออกจากกล่องรีเซต']])+steps(['อ่านเงื่อนไข Active test ก่อนสั่งอุปกรณ์','ใช้ scan tool ที่รองรับและรักษาพื้นที่ปลอดภัย','ห้ามจัมป์ขา Output หรือเพิ่มฟิวส์เพื่อบังคับโหลด']));
add('03 / ECU และ VCU','CAN ในกล่อง: แยก logic กับสายบัส','การอ่านไฟเลี้ยง transceiver ช่วยลดการเปลี่ยนกล่องผิด',fig(['MCU|TX / RX','Transceiver|logic ↔ bus','Protection|ESD / choke','Connector|CAN-H / CAN-L'],'เส้นทางสื่อสารบน PCB แบบย่อ')+checks([['กล่องหายจากเครือข่าย','ตรวจไฟ กราวด์ Wake และ topology','กล่องไม่ตื่นไม่เท่ากับ CAN IC เสีย'],['มีบัสแต่กล่องไม่ตอบ','ดูไฟเลี้ยงและขา Standby ตาม datasheet','โหมดพักอาจถูกสั่งจาก MCU'],['CAN ชอร์ตเฉพาะกิ่ง','แยกตามผังเมื่อปลอดไฟและ OEM อนุญาต','ทำ baseline ก่อนถอดทุกครั้ง'],['PCB มีคราบน้ำ','ตรวจหลังแยกจากรถอย่างปลอดภัย','ต้องประเมินรอยกัดกร่อนใต้ชิ้นส่วน ไม่เพียงล้างผิว']])+slot('C','ภาพ VCU PCB และ CAN transceiver จริงที่มีสิทธิ์ใช้ พร้อมรุ่นบอร์ด'),['S2']);
add('03 / ECU และ VCU','Connector / Pinout: แผ่นงานยืนยัน','ใช้เป็นใบตรวจหัวต่อ ไม่ใช่ pinout สำเร็จรูป',slot('A','Connector VCU: มุมมองด้านขั้วและด้านสาย พร้อมเลขขาที่ตรวจสอบได้')+table(['หน้าที่ที่ต้องค้นในผัง OEM','ข้อมูลที่ต้องกรอก','สิ่งที่ห้ามเดา'],[['ไฟเลี้ยงถาวร / IGN / Wake','รหัสหัวต่อ ____ ขา ____ หน้าเอกสาร ____','ห้ามใช้ตำแหน่งจากรถรุ่นคล้ายกัน'],['Ground / Sensor return','จุดกราวด์ ____ เส้นทาง ____','ห้ามรวมกราวด์ทุกชนิดเอง'],['CAN-H / CAN-L','ชื่อเครือข่าย ____ Gateway ____','ห้ามถือว่าถึง DLC โดยตรง'],['Input / Output','พิกัด/เงื่อนไขทดสอบ ____','ห้ามโหลดหรือป้อนไฟเพื่อทดสอบโดยไม่มีข้อมูล']])+steps(['แนบภาพหัวต่อที่เห็นสลักครบและภาพฉลากกล่อง','เทียบหมายเลข cavity กับผังฉบับตรงรุ่น แล้วลงชื่อผู้ยืนยัน','หากข้อมูลขัดกัน หยุดวัดขานั้นและค้นเอกสารใหม่'])+field());

add('04 / BMS','BMS: มองข้อมูลเป็นกลุ่ม','ค่าจาก BMS ต้องสอดคล้องกับอุณหภูมิและสภาพโหลด',fig('bms','Cell monitor, ข้อมูลอุณหภูมิ กระแส และ MCU')+checks([['แรงดันรายเซลล์/บล็อก','บันทึกต่ำสุด สูงสุด และหมายเลขช่อง','ช่องข้อมูลอาจเป็นกลุ่มเซลล์ ไม่ใช่เซลล์เดี่ยว'],['อุณหภูมิ','บันทึกทุกโซนและสภาพแวดล้อม','ความต่างสัมพันธ์กับตำแหน่งและระบบระบายความร้อน'],['กระแสแพ็ก','ดูทิศและเครื่องหมายจากคู่มือ','ไม่สมมติว่าค่าบวกคือชาร์จทุกยี่ห้อ'],['การอนุญาตชาร์จ/ขับ','อ่านข้อจำกัดกำลังพร้อม DTC','ขีดจำกัดอาจมาจากอุณหภูมิหรือ SOC']])+note('AFE (Analog Front End) คือภาครับสัญญาณก่อนแปลงข้อมูล การเชื่อมช่องวัดเซลล์อยู่บนศักย์ HV แม้แรงดันต่างระหว่างช่องต่ำ'),['S3']);
add('04 / BMS','แรงดัน Cell: ค่าผิดกับสายวัดผิด','เริ่มจากข้อมูลสแกนก่อนเปิดระบบแบตเตอรี่',fig('bms','ทางวัดเซลล์เป็นภาพหลักการ ไม่ใช่ลำดับถอดสาย sense')+checks([['ช่องหนึ่งสูง/ต่ำผิดกลุ่ม','ดูช่องข้างเคียงพร้อม DTC ของวงจรวัด','อาจเป็นสาย sense เปิด ไม่ใช่เซลล์เสื่อม'],['ค่าแกว่งกับโหลด','เทียบกระแส อุณหภูมิ และแรงดันช่อง','ต้องเทียบภายใต้เงื่อนไขเดียวกัน'],['ผลรวมไม่ตรงแรงดันแพ็ก','ตรวจหน่วยและวิธีรวม PID','PID อาจปรับอัตรา/กรองต่างกัน'],['ต้องยืนยันวัดตรง','ส่งผู้ชำนาญ HV ใช้คู่มือและเครื่องมือเฉพาะ','ไม่เอาโพรบทั่วไปไล่ขา sense']])+note('PID คือรายการข้อมูลที่เครื่องสแกนแสดง ΔV = ค่าสูงสุด − ต่ำสุด แต่ไม่มีค่า ΔV เดียวที่ใช้ตัดสินแบตเตอรี่ทุกเคมี ทุก SOC และทุกโหลดได้'));
add('04 / BMS','Temperature Sensor: แยกวงจรกับความร้อน','อ่านช่วงเย็นเทียบสิ่งแวดล้อมก่อนดูช่วงใช้งาน',fig(['NTC sensor|temperature → R','Divider / filter|signal conditioning','ADC|digital value','BMS|limits / cooling'],'ทางสัญญาณอุณหภูมิแบบย่อ; NTC คือเทอร์มิสเตอร์ที่ R ลดเมื่ออุณหภูมิสูงขึ้น')+checks([['ค่าต่ำ/สูงสุดตลอด','ดู DTC open/short และหน่วยข้อมูล','ค่าปลายช่วงอาจเป็นค่าทดแทนเมื่อวงจรเสีย'],['โซนหนึ่งร้อนกว่ากลุ่ม','ดูทิศลม/น้ำหล่อเย็นและประวัติโหลด','อาจมีความร้อนจริง ไม่ใช่เซนเซอร์เพี้ยน'],['หลังจอดเย็นนาน','เทียบหลายโซนกับอุณหภูมิรอบรถ','ไม่ต้องคาดว่าทุกจุดเท่ากันทันที'],['วัด R ของ NTC','เฉพาะสภาพและจุดที่ OEM อนุญาต','ต้องมีตาราง R–T ของชิ้นส่วนจริง']])+note('ห้ามใช้ค่าโอห์มของ NTC รุ่นหนึ่งไปตัดสินอีกรุ่น และห้ามชอร์ตเซนเซอร์เพื่อหลอกให้ระบบทำงาน'));
add('04 / BMS','Current Sensor: ศูนย์เพี้ยนทำให้คำนวณผิด','เซนเซอร์อาจเป็น Hall effect หรือ Shunt แยกวงจร',fig(['Pack current|HV conductor','Hall / Shunt|isolated sensing','BMS data|offset + direction','SOC estimate|cross-check'],'การวัดกระแสและความสัมพันธ์กับการประเมินประจุ')+checks([['กระแสขณะไม่มีโหลดตามเงื่อนไข','ดู offset และค่าทดแทนที่สแกนแสดง','ห้ามสรุปผิดจากค่าศูนย์ที่ไม่ตรงเงื่อนไข OEM'],['กระแสกลับทิศ','ยืนยัน sign convention ก่อน','เทียบการชาร์จและคืนพลังงานที่อนุญาต'],['สัญญาณค้าง','ดูไฟเลี้ยง สัญญาณ และ DTC','สายหรือ reference ผิดก็ทำให้ค้างได้'],['เปรียบเทียบแคลมป์มิเตอร์','เฉพาะผู้ชำนาญ HV และสายที่เข้าถึงได้ปลอดภัย','ไม่เปิดฉนวนหรือแยกบัสบาร์เพื่อหนีบ']])+note('ห้ามถอด/ย้ายเซนเซอร์บนแพ็กที่ยังมีพลังงานตามวิธีทั่วไป ต้องใช้ขั้นตอนเฉพาะแบตเตอรี่'));
add('04 / BMS','Cell Balancing: ไม่ใช่การซ่อมเซลล์เสีย','Passive balancing ระบายประจุผ่านตัวต้านทาน',fig('balance','แขนงระบายพลังงานต่อคร่อมเซลล์แบบหลักการ')+table(['สิ่งที่ดู','บันทึก','ความหมาย'],[['คำสั่ง balancing','สถานะช่อง ระยะเวลา และเงื่อนไข','ไม่ทำงานได้เมื่อยังไม่เข้าเงื่อนไข'],['อุณหภูมิวงจร','ก่อน/ระหว่าง/หลังคำสั่งที่อนุญาต','ความร้อนเป็นผลจากการระบายพลังงาน'],['แรงดันช่อง','เทียบก่อนและหลังในสภาพเดียวกัน','การลดช่องสูงไม่เพิ่มความจุช่องต่ำ'],['เซลล์อ่อนภายใต้โหลด','เทียบข้อมูลรอบตรวจที่สอดคล้องกัน','สมดุลแรงดันขณะพักไม่ยืนยันความจุ']])+note('ไม่ใส่ตัวต้านทานภายนอกคร่อมช่องเซลล์เพื่อทดลอง และไม่สั่ง balancing เพื่อแก้อาการรถน้ำท่วม ความผิดปกติของฉนวนต้องจัดการก่อน',true),['S3']);
add('04 / BMS','Contactor และ Precharge','ดูสถานะคำสั่งกับแรงดันบัสตามเวลา',fig('contactor','Precharge จำกัดกระแสเข้า DC-link ก่อนต่อวงจรหลัก')+checks([['ไม่สั่งคอนแทกเตอร์','ดู HVIL ฉนวน การชน และเงื่อนไขอนุญาต','ห้าม bypass เพื่อทดลอง'],['สั่งแล้วบัสไม่ขึ้น','อ่านแรงดันแพ็ก/บัส และ DTC รหัสย่อย','อาจเป็นวงจร precharge หรือโหลดผิดปกติ'],['บัสขึ้นแล้วตัด','จับกราฟคำสั่งและเหตุผลยกเลิก','แยก timeout กับ feedback ไม่สัมพันธ์'],['สงสัยหน้าสัมผัสเชื่อมติด','หยุดตามแผนบริการ OEM','อย่าพยายามบังคับเปิด–ปิดซ้ำ']])+slot('A','วงจร BMS/Contactor/Precharge จริงตามรุ่น พร้อมหมายเลขจุดวัด')+note('เวลารอคายประจุและเกณฑ์แรงดันต้องใช้คู่มือรถนั้น ไม่ใช้จำนวนวินาทีหรือค่าแรงดันสำเร็จรูปจากหนังสือเล่มนี้',true));

add('05 / Inverter และ Motor','แผนที่ชุดขับเคลื่อน','แยกคำสั่งควบคุมออกจากภาคกำลัง',fig('inverter','สะพานสวิตช์สามเฟส พร้อมข้อมูลป้อนกลับ')+checks([['ไม่เกิดแรงบิด','ดูคำสั่ง torque และข้อจำกัดจาก VCU/BMS','ถ้าไม่อนุญาตขับ ห้ามเริ่มจากเปลี่ยนภาคกำลัง'],['มีคำสั่งแต่ตัด','ดู DTC subcode กระแส ตำแหน่งโรเตอร์ อุณหภูมิ','เชื่อมข้อมูลที่มีเวลาเดียวกัน'],['บัส HV ไม่พร้อม','ย้อนตรวจ precharge และ BMS','ไม่สรุปมอเตอร์เสียจากอาการไม่หมุน'],['ระบบคืนพลังงานจำกัด','ดู SOC / อุณหภูมิ / การยึดเกาะ','ไม่ใช่ความผิดปกติเสมอไป']])+slot('C','ภาพ Inverter และ Motor จริง แสดงฉลากและหัวต่อ โดยได้รับสิทธิ์ใช้'));
add('05 / Inverter และ Motor','Gate Driver และสวิตช์กำลัง','ไม่วัด Gate บนรถด้วยเครื่องมือทั่วไป',fig('inverter','MCU ส่ง PWM ผ่าน driver ที่มีการแยกไฟ')+table(['ชิ้นส่วน','หน้าที่','เบาะแส / ข้อจำกัด'],[['IGBT','ทรานซิสเตอร์กำลังแบบไบโพลาร์ควบคุมด้วยเกต','ทดสอบตามคู่มือชิ้นส่วน ไม่ใช้เกณฑ์ MOSFET แทน'],['MOSFET','สวิตช์ควบคุมด้วยแรงดันเกต','วงจรขนานทำให้ผล diode test ตีความยาก'],['SiC MOSFET','MOSFET วัสดุซิลิคอนคาร์ไบด์','สวิตช์เร็ว ต้องใช้โพรบและวิธีวัดเหมาะสม'],['Gate driver','ขับเกตและป้องกันตามการออกแบบ','fault อาจมาจากไฟเลี้ยง driver หรือภาคกำลัง'],['Dead time','ช่วงเว้นไม่ให้สวิตช์บน–ล่างนำพร้อมกัน','ห้ามปรับเพื่อทดลองโดยไม่มีข้อมูลวิศวกรรม']])+note('การวัดภาคกำลังมีแรงดันและ dV/dt สูง ให้ใช้ผู้ชำนาญและขั้นตอน OEM หนังสือไม่ให้ขั้นตอนจ่ายไฟ HV บนโต๊ะ',true));
add('05 / Inverter และ Motor','Current Feedback: ใช้ข้อมูลหลายทางยืนยัน','หนึ่งช่องเพี้ยนอาจทำให้ระบบจำกัดแรงบิด',fig(['Phase currents|sensors','ADC / isolation|conversion','Control loop|torque control','Protection|limit / shutdown'],'สัญญาณกระแสเฟสเป็นข้อมูลควบคุมและป้องกัน')+checks([['กระแสช่องหนึ่งต่าง','ตรวจเงื่อนไขเวลาและการกรอง PID','PID ที่อ่านไม่พร้อมกันใช้เทียบผลรวมทันทีไม่ได้'],['offset เมื่อเข้าเงื่อนไขศูนย์','เทียบข้อกำหนดผู้ผลิต','ค่าทดแทนหรือสัญญาณขาดต้องแยกก่อน'],['ตัดเมื่อเพิ่มโหลด','เทียบกระแสจริง ข้อจำกัด และอุณหภูมิ','ไม่เร่งซ้ำเพื่อบังคับให้เสียชัด'],['สายสัญญาณ/ซีล','ตรวจหลังแยกและพิสูจน์ปลอดภัยตามขั้นตอน','คราบน้ำอาจทำให้สัญญาณรั่ว']])+steps(['เก็บ DTC และข้อมูลประกอบก่อนล้าง','เทียบเหตุการณ์เดียวกันจาก VCU/BMS/Inverter','หากต้องวัดสดภาค HV ให้ส่งงานตามระดับความชำนาญ']));
add('05 / Inverter และ Motor','Motor Position Sensor','Resolver กับ Encoder ใช้ขั้นตอนตรวจต่างกัน',fig(['Excitation|resolver only','Rotor position|sin/cos or digital','Inverter MCU|angle / speed','Torque control|plausibility'],'เส้นทางข้อมูลตำแหน่งโรเตอร์แบบย่อ')+checks([['รหัสตำแหน่ง/ความเร็ว','อ่านชื่อ sensor และรหัสย่อยตรงรุ่น','ห้ามใช้ชื่อ resolver กับทุกมอเตอร์'],['ไม่หมุน/สะดุด','เทียบคำสั่งแรงบิดกับ speed/angle ที่สแกนรองรับ','ไม่ทดสอบขับถ้ามีความเสี่ยงควบคุมแรงบิด'],['หัวต่อโดนน้ำ','ตรวจซีล การกัดกร่อน และแรงยึดขั้ว','เช็ดแห้งไม่ยืนยันคุณภาพหน้าสัมผัส'],['เปลี่ยนมอเตอร์/ชุดควบคุม','ตรวจเงื่อนไขเรียนรู้ตำแหน่งตาม OEM','ไม่ทำ calibration โดยเดาค่ามุม']])+note('ห้ามหมุนล้อขับหรือมอเตอร์โดยไม่ดูวิธีกู้/ลากเฉพาะรุ่น เพราะมอเตอร์อาจสร้างแรงดันกลับได้',true),['S1']);
add('05 / Inverter และ Motor','ระบบหล่อเย็นและอาการตัดกำลัง','รหัส Inverter ไม่ได้แปลว่าต้องเปลี่ยนทั้งชุด',fig(['Temp high?|confirm data','Cooling command|pump / fan','Flow / leak|OEM procedure','Retest|same conditions'],'กระบวนการแยกความร้อนจริงออกจากข้อมูลผิด')+checks([['อุณหภูมิขึ้นเร็ว','ตรวจค่าเริ่มต้นและเซนเซอร์หลายจุด','เริ่มจากข้อมูลผิดก่อนจำลองโหลดหนัก'],['ปั๊มถูกสั่งแต่ไม่ไหล','ตรวจไฟ/กราวด์/กระแสในฝั่งที่อนุญาต','มีเสียงปั๊มไม่ยืนยันการไหล'],['น้ำหล่อเย็นต่ำ','ตรวจรอยรั่วตามคู่มือ ห้ามเปิดฝาร้อน','บางระบบเกี่ยวข้องกับแพ็ก ต้องประเมินฉนวน'],['มี P0A94 / กลุ่ม IPM','ค้น TSB/recall ตาม VIN และ subcode','ห้ามใช้รหัสเดียวอนุมัติเปลี่ยนชุด']])+slot('A','วงจรปั๊มหล่อเย็น Inverter จริงตามรุ่นและ revision'),['S6','S7']);

add('06 / Charging','AC กับ DC: เส้นทางไม่เหมือนกัน','OBC คือเครื่องแปลงไฟชาร์จที่ติดตั้งในรถ',fig('charging','AC ผ่าน OBC; DC ใช้เครื่องแปลงภายนอกในสถาปัตยกรรมทั่วไป')+checks([['AC ไม่เข้า แต่ DC เข้า','ตรวจ inlet, CP/PP และเส้นทาง OBC ตามรถ','ยังไม่ยืนยันว่า OBC เสีย'],['DC ไม่เข้า แต่ AC เข้า','ตรวจการสื่อสาร ล็อกหัว และความเข้ากันได้','เส้นทาง DC และเงื่อนไขต่างจาก AC'],['ทั้งสองแบบไม่เข้า','เริ่มจาก LV, BMS และการอนุญาตชาร์จ','ดู SOC อุณหภูมิ ฉนวน และประวัติน้ำ'],['เสียเฉพาะสถานี','บันทึกสถานี เวลา และข้อความผิดพลาด','ทดสอบกับอุปกรณ์ที่ยืนยันดีเมื่อรถปลอดภัย']])+note('EVSE (Electric Vehicle Supply Equipment) คืออุปกรณ์จ่ายพลังงานให้รถ การชาร์จ DC ไม่ได้ใช้เส้นทางภาคกำลัง OBC แบบ AC ในรถทั่วไป'));
add('06 / Charging','OBC: แยกกำลังเข้า การอนุญาต และกำลังออก','วินิจฉัยจากข้อมูลสแกนก่อนเปิดชุดชาร์จ',fig(['AC inlet|port / lock','EMI + PFC|input stage','Isolated DC-DC|conversion','HV battery|BMS permission'],'โครงสร้างหน้าที่ OBC แบบย่อ; PFC คือการปรับตัวประกอบกำลัง')+checks([['เสียบแล้วไม่รับรู้','ดู plug present และ port lock','เริ่มจากหัวต่อและวงจรตรวจเสียบ'],['รับรู้แต่ไม่เริ่ม','ดู permission และ DTC ทุกกล่อง','อุณหภูมิหรือฉนวนอาจบล็อกชาร์จ'],['เริ่มแล้วหยุด','จับเวลา แรงดัน กระแส อุณหภูมิ และ EVSE fault','แยกฝั่งรถกับฝั่งสถานี'],['OBC precharge fault','ใช้ชื่อรหัสและขั้นตอนเฉพาะรุ่น','P0D26 มีตัวอย่างการใช้งานใน Mitsubishi PHEV']])+slot('C','ภาพ OBC จริงพร้อมฉลากรุ่นและหลักฐานสิทธิ์'),['S11']);
add('06 / Charging','DC-DC: ตรวจทั้ง Enable และฝั่ง LV','อย่าตีความ P0A94 ว่าเป็นกล่องชาร์จ 12 V เสมอ',fig(['HV supply|protected input','DC-DC|isolated converter','LV network|battery + loads','Feedback|VCU / ECU'],'ตัวแปลง HV เป็น LV ในสถาปัตยกรรมทั่วไป')+checks([['LV ไม่เพิ่มเมื่อ READY','ดูคำสั่ง Enable และเป้าหมายแรงดัน','บางรถควบคุมแรงดันตามสภาพ ไม่ใช้เลขเดียว'],['แรงดันตกเมื่อโหลดมาก','เทียบกระแส พิกัด คำสั่ง และสายจ่าย','สายหรือขั้วมีความต้านทานสูงก็ทำให้ตก'],['แบตเตอรี่ LV คายประจุ','ตรวจสุขภาพแบตเตอรี่และ sleep current ตาม OEM','ไม่ใช่ DC-DC เสียเสมอ'],['มี P0A94 ในไฮบริด Toyota','อ่าน INF/subcode และผัง converter','อาจเกี่ยวข้อง boost converter ใน Inverter']])+note('ก่อนถอดแบตเตอรี่ LV ให้ดูขั้นตอน OEM และผลต่อการนอนของระบบ ห้ามถอดขั้วเพื่อทดสอบการชาร์จขณะรถทำงาน'),['S6','S7']);
add('06 / Charging','Charge Port และการสื่อสาร','ไม่มี pinout เดียวใช้ได้ทุกหัวชาร์จ',fig(['EVSE|pilot / protocol','Inlet|CP / PP / lock','Charge ECU|handshake','BMS|limits / permission'],'สัญญาณขึ้นกับมาตรฐานหัวชาร์จ; ไม่แสดงหมายเลขขา')+table(['สิ่งที่ต้องระบุ','ตรวจเบื้องต้น','ขอบเขต'],[['ชนิดหัวชาร์จ / AC-DC','ดูฉลากรถและคู่มือ','ห้ามนำสัญญาณ CCS ไปใช้กับ GB/T โดยตรง'],['CP: Control Pilot','สัญญาณแจ้งสถานะ/ข้อจำกัดในระบบที่ใช้ CP','ต้องใช้ adaptor และสโคปที่เหมาะสม'],['PP: Proximity Pilot','ตรวจสาย/หัวชาร์จตามมาตรฐานที่รถใช้','วงจรและค่าต่างกันตามระบบ'],['DC communication','ระบุว่าเป็น PLC, CAN หรือระบบอื่นจากคู่มือ','ห้ามสรุปว่าทุก DC charger ใช้ CAN'],['Port lock / อุณหภูมิ','ดูสถานะและ DTC พร้อมสภาพจริง','ห้ามฝืนปลดล็อกหรือจัมป์เซนเซอร์']])+note('ไม่ฉีดน้ำยาหรือแหย่ขั้วชาร์จที่อาจมีพลังงาน ให้ตรวจตามขั้นตอนทำให้ปลอดภัยของผู้ผลิต'),['S10']);
add('06 / Charging','ชาร์จผิดปกติ: แยกสาเหตุอย่างมีหลักฐาน','หลังน้ำท่วม ห้ามใช้การเสียบชาร์จเป็นการทดสอบ',fig(['Vehicle safe?|flood / damage','Read all ECUs|codes + status','Compare source|known-good EVSE','Confirm repair|charge log'],'การวิเคราะห์ชาร์จหลังผ่านการประเมินความปลอดภัย')+checks([['ไม่เริ่มเลย','ดู plug/lock/schedule/SOC/permission','แยกการตั้งเวลาออกจากวงจรเสีย'],['เริ่มแล้วตัด','บันทึกวินาทีที่ตัดและ DTC ล่าสุด','อย่าลบก่อนเก็บข้อมูล'],['กระแสต่ำ','ดูอุณหภูมิ SOC และขีดจำกัดจาก EVSE','อาจเป็น derating (ลดกำลังเพื่อป้องกัน)'],['ฉนวนผิดปกติ/น้ำเข้าพอร์ต','หยุดการทดลองชาร์จ','ส่งตรวจตามแผน OEM ไม่เป่าแห้งแล้วลองซ้ำ']])+steps(['เก็บภาพข้อความรถและสถานี พร้อมวันเวลา','จับคู่ event log ฝั่งรถกับสถานีเมื่อหาได้','ทวนสอบหลังซ่อมในสภาพและระดับกำลังที่คู่มืออนุญาต']),['S8']);

add('07 / CAN Bus','CAN-H / CAN-L และ Termination','ตัวต้านทานปลายสายทำงานเป็นคู่ใน HS-CAN แบบทั่วไป',fig('can','บัสสองสายกับตัวต้านทานปลายสาย 120 Ω สองตัว')+checks([['วัดระหว่าง H–L','เฉพาะบัสที่ปลอดไฟและเข้าสภาพตาม OEM','แบบตัวอย่าง 120 || 120 = 60 Ω'],['อ่านใกล้ 120 Ω','ตรวจว่าปลายหนึ่งขาดหรือถูกแยกหรือไม่','ไม่ใช่ข้อสรุปตายตัวในเครือข่ายมี Gateway'],['อ่านต่ำกว่าคาด','มองหา termination เกิน/ชอร์ต/วงจรขนาน','ดู topology ก่อนถอดกล่อง'],['อ่านเปิดวงจร','ตรวจจุดวัดและเส้นทางถึงบัส','Gateway อาจแยกจากเครือข่ายที่ต้องการ']])+note('ค่าโอห์มต้องวัดเมื่อไม่มีแรงดัน ห้ามเลือกโหมด Ω บนบัสที่ยังทำงาน ห้ามเพิ่มตัวต้านทานเพื่อกลบอาการ'),['S2']);
add('07 / CAN Bus','วงจร CAN จริงที่ศึกษาได้','ตัวอย่างบอร์ดพัฒนา Adafruit CAN Bus BFF ไม่ใช่ ECU รถ',`<figure class="actual"><img src="assets/can-schematic.png" alt="วงจรจริง Adafruit CAN Bus BFF"><figcaption><b>A · Actual Wiring Diagram</b> — Schematic ของ Adafruit CAN Bus BFF (บอร์ดตัวอย่าง)<br>ผู้สร้าง Adafruit Industries • S12/S13 • CC BY-SA 2.5 (ตามกรอบภาพ) • คงภาพต้นฉบับ ย่อเพื่อจัดหน้า • ไม่ใช่ผังสายไฟ OEM ของรถ</figcaption></figure>`+table(['ติดตามจากภาพต้นฉบับ','หน้าที่','ใช้เรียนรู้อะไร'],[['MCP25625','CAN controller พร้อม transceiver','แยกการสื่อสาร SPI ฝั่ง MCU กับคู่สาย CAN'],['ไฟเลี้ยงและ decoupling','จ่ายไฟและกรองใกล้ IC','วงจรขาดไฟทำให้ดูเหมือนเครือข่ายเสีย'],['Termination','โหลดปลายสายบนบอร์ด','จำนวนตัวต้านทานต้องสอดคล้อง topology'],['NEOGS1 / JST PH 3','ขา 1 GND · ขา 2 CAN_H · ขา 3 CAN_L','ยืนยันจาก schematic นี้เท่านั้น ไม่ใช่ pinout รถ']])+note('ไฟล์ภาพความละเอียดเต็มอยู่ในโฟลเดอร์ assets เปิดขยายก่อนอ่านตัวเลข ห้ามเทียบเลขขาของบอร์ดนี้กับหัวต่อรถ'),['S12','S13']);
add('07 / CAN Bus','ภาพอุปกรณ์จริง: อ่าน PCB และหัวต่อ','ตัวอย่างสำหรับฝึกสังเกต ไม่ใช่กล่องควบคุมรถ',`<figure class="photo"><img src="assets/can-bff.jpg" alt="ภาพถ่ายบอร์ด Adafruit CAN Bus BFF"><figcaption><b>C · Actual Component Photograph</b> — บอร์ด Adafruit CAN Bus BFF<br>Adafruit Industries • assets/5877.jpg จาก S12 • CC BY-SA 3.0 ตาม license.txt ของ repository • ไม่ดัดแปลง ย่อจัดหน้า • เป็นภาพถ่ายจริง</figcaption></figure>`+checks([['สังเกตฉลากและตำแหน่งหัวต่อ','จับคู่กับ schematic หน้า 32','อย่าใช้รูปร่าง IC เพียงอย่างเดียวระบุรุ่น'],['มองหาการกัดกร่อน/ชิ้นส่วนหลุด','ใช้ภาพก่อน–หลังภายใต้แสงเดียวกัน','ภาพตัวอย่างนี้ไม่ได้อ้างว่าเป็นบอร์ดน้ำท่วม'],['หัวต่อและจุดบัดกรี','ฝึกแยกขั้วชิ้นส่วนกับแนวลายวงจร','งานรถต้องยืนยัน revision จริง'],['ตรวจสิทธิ์ภาพ','เก็บไฟล์ใบอนุญาตคู่กับภาพ','ไฟล์ภาพที่อื่นอาจใช้สิทธิ์ต่างกัน']]),['S12']);
add('07 / CAN Bus','รูปคลื่น CAN: ดูผลต่างและคุณภาพสัญญาณ','ภาพนี้เป็นอุดมคติเพื่อการเรียนรู้ ไม่ใช่ภาพจับจริง',fig('wave','ตัวอย่าง 5 V HS-CAN; recessive ใกล้ 2.5 V ทั้งคู่ dominant ประมาณ H 3.5 / L 1.5 V')+checks([['ใช้สโคปสองช่องหรือ differential','อ้างอิงกราวด์ LV ตามคู่มือและพิกัดเครื่องมือ','ดู H−L พร้อมแต่ละเส้น'],['ทั้งสองเส้นเคลื่อนพร้อมกัน','ตรวจ common-mode และกราวด์','ไม่สรุปจาก differential อย่างเดียว'],['ขอบสั่น/สะท้อน','ตรวจ termination สายกิ่ง และจุดต่อ','การตั้งสโคป/โพรบเองก็ทำให้เห็นผิด'],['เส้นหนึ่งค้าง / ไม่สื่อสาร','ตรวจ short/open พร้อม topology','มิเตอร์แสดงค่าเฉลี่ย ไม่ยืนยันรูปคลื่น']])+note('ตัวเลขในภาพเป็นค่าตัวอย่างของ HS-CAN ทั่วไป ไม่ใช่เกณฑ์ทุก transceiver หรือทุกโหมดของ CAN FD ต้องดู datasheet และสเปกรถ'),['S2']);
add('07 / CAN Bus','ไล่กล่องหายและ U-code','เริ่มจากผู้รายงานรหัส ไม่ใช่เปลี่ยนกล่องที่ถูกกล่าวถึง',fig(['Scan topology|who reports?','LV / wake|shared supply','Bus segment|H/L + gateway','Target ECU|local evidence'],'แผนผังวินิจฉัยเครือข่ายโดยใช้จุดร่วม')+checks([['หลายกล่องรายงานหา BMS ไม่พบ','ดูไฟ/กราวด์/Wake BMS และบัสกิ่งนั้น','อาจมีสาเหตุร่วมเพียงจุดเดียว'],['บางกล่องหายบางครั้ง','จับเวลา undervoltage กับ U-code','แรงดัน LV ตกอาจทำให้กล่องรีเซต'],['CAN วัดได้ปกติแต่สแกนไม่ได้','ดู Gateway การอนุญาต และโปรโตคอลเครื่องมือ','บัสมีพัลส์ไม่เท่ากับข้อความถูกต้อง'],['หลังน้ำเข้าหัวต่อ','ตรวจเมื่อแยกไฟตาม OEM แล้ว','อย่าเสียบ–ถอดบัสสดเพื่อสุ่มหากล่อง']])+steps(['ทำรายการกล่องที่ตอบ/ไม่ตอบพร้อมสถานะรหัส','เลือกจุดร่วมจาก topology แทนการถอดทุกกล่อง','ยืนยันการตื่นและการสื่อสารกลับมาหลังซ่อม']),['S14']);

const dtcHead=['รหัส / ขอบเขต','อาการและหลักฐาน','ตรวจลำดับแรก / ห้ามด่วนสรุป'];
add('08 / DTC','อ่าน DTC ให้ครบก่อนวางแผนซ่อม','รหัสคือทิศทางตรวจ ไม่ใช่ใบสั่งเปลี่ยนอะไหล่',table(['ข้อมูล','ต้องบันทึก','เหตุผล'],[['รหัสเต็ม','P/U/B/C + suffix/INF + กล่องที่บันทึก','ฐานรหัสเดียวมีเงื่อนไขและสาเหตุต่างกัน'],['สถานะ','Current / Pending / History / Permanent ตามเครื่องมือ','รหัสเก่าอาจไม่ใช่อาการปัจจุบัน'],['Freeze frame','เวลา แรงดัน SOC อุณหภูมิ ความเร็ว','ช่วยแยกเหตุและผล'],['ข้อมูลรถ','VIN ปี ตลาด software และรายการซ่อมก่อนหน้า','ชื่อ DTC และขั้นตอนอาจต่างกัน'],['เอกสาร','TSB/recall ใช้ได้กับ VIN หรือไม่','เอกสารรถหนึ่งรุ่นไม่ใช้เหมาทุก EV']])+fig(['อ่านทั้งหมด|ไม่ลบก่อน','เรียงเหตุการณ์|root cause?','พิสูจน์สาเหตุ|measure','ซ่อม + ตรวจซ้ำ|conditions'],'ขั้นตอนใช้ DTC ในงานวิเคราะห์')+note('ตารางหน้า 37–42 เลือกรหัสที่มีหลักฐานบริการ/บันทึกจริงจากแหล่งอ้างอิง ไม่จัดอันดับความถี่ข้ามยี่ห้อ เพราะไม่มีฐานสถิติเปรียบเทียบ รหัสของไฮบริดไม่จำเป็นต้องมีใน BEV ทุกคัน'));
add('08 / DTC','P0AA6: ความผิดปกติของฉนวน HV','สัมพันธ์กับความชื้นได้ แต่ไม่ใช่รหัสยืนยันรถน้ำท่วม',table(dtcHead,[['P0AA6<br>Hybrid/EV battery voltage system isolation fault','อาจไม่ READY หรือชาร์จไม่ได้; เก็บรหัสย่อย/INF หากรองรับและกล่องผู้รายงาน','ตรวจประวัติ น้ำ/การชน ข้อมูลฉนวนและเอกสาร OEM ก่อน'],['ตัวอย่างหลักฐาน S5<br>GM Volt/ELR/Ampera ตามปีใน bulletin','เอกสารเชื่อมอาการชาร์จไม่ได้กับการสูญเสียฉนวน','ดู applicability; ไม่ยกวิธีซ่อมไปใช้ EV ทุกคัน'],['ความเป็นไปได้เชิงวินิจฉัย','แพ็ก สาย HV อุปกรณ์ HV หรือการรั่วของของเหลว','แยกวงจรเฉพาะตาม OEM ห้ามไล่ถอดสด'],['หลังน้ำท่วม','มีประวัติสัมผัสน้ำหรือคราบและข้อมูลผิดปกติ','หยุดทดลอง READY/ชาร์จ ส่งผู้ชำนาญ HV']])+steps(['เก็บ DTC เต็ม ค่า isolation ที่รถรายงาน และเงื่อนไขอุณหภูมิ/ความชื้น','ประเมินความปลอดภัย แล้วใช้ flowchart เฉพาะรุ่นระบุส่วนที่ต้องแยก','ซ่อมตามสาเหตุ ยืนยันผลด้วยวิธี OEM และเงื่อนไขที่อนุญาต'])+note('ห้ามต่อ insulation tester เข้าชุดอิเล็กทรอนิกส์ที่ยังเชื่อมอยู่โดยเดาแรงดันทดสอบ อาจทำลายอุปกรณ์และเป็นอันตราย แรงดันทดสอบ จุดแยก และเกณฑ์ผ่านต้องระบุจาก OEM',true),['S5','S8']);
add('08 / DTC','P0A80 / P0A7F: แบตเตอรี่ไฮบริด','เริ่มจากข้อมูลและระบบหล่อเย็น ไม่ใช้รหัสอย่างเดียวตัดสิน',table(dtcHead,[['P0A80<br>Replace Hybrid Battery Pack','ชื่อรหัสเป็นข้อบ่งชี้ของระบบตรวจ ไม่ใช่ขั้นตอนซ่อมทันที','เทียบ block data, SOC, กระแส อุณหภูมิ และเอกสารรุ่น'],['P0A7F<br>Hybrid Battery Pack Deterioration','ระบบประเมินการเสื่อมตามเงื่อนไขผู้ผลิต','ตรวจรหัสย่อย ประวัติซ่อมและความต่างภายใต้โหลด'],['หลักฐาน S4<br>Camry HV ปี 2013–2014 ตลาดสหรัฐฯ','Toyota ระบุอาการที่เกี่ยวข้องกับฝุ่น/เศษสิ่งสกปรกในทางระบายอากาศ','ใช้ T-SB-0049-14 Rev1 ตาม VIN และเงื่อนไข เมื่อตรงเงื่อนไข TSB ให้จัดการพัดลม/ไส้กรองและเปลี่ยน HV Battery Assembly ตามเอกสาร ไม่ใช่ล้างพัดลมอย่างเดียว'],['หลังน้ำท่วม','แบตเตอรี่ผิดสมดุลอาจมีหลายสาเหตุ','รหัสสองตัวนี้ไม่ระบุชนิดน้ำหรือยืนยันน้ำเข้าแพ็ก']])+checks([['ข้อมูลที่เก็บ','ทุก block, กระแส, SOC, temp, fan command','เทียบเวลาเดียวกัน'],['งานตรวจที่เริ่มได้','ตรวจช่องลมภายนอกตามคู่มือและสภาพปลอดภัย','ไม่เปิดแพ็กเพื่อสลับเซลล์ทดลอง'],['ยืนยันผล','ทำขั้นตอนตรวจทานตาม OEM และรายงานผล','ไม่ใช้ไฟเตือนดับเป็นเกณฑ์เดียว']]),['S4']);
add('08 / DTC','กลุ่ม Inverter: P0A78 / P0A7A / P0A94','ตัวอย่างหลักฐานงานบริการไฮบริด Toyota',table(dtcHead,[['P0A78<br>Drive Motor A Inverter Performance','ระบบประเมินสมรรถนะ Inverter ขับมอเตอร์ A','อ่าน subcode, freeze frame, software และสภาพระบบ'],['P0A7A<br>Generator Inverter Performance','เกี่ยวกับภาค Inverter เครื่องกำเนิดในระบบที่ใช้รหัสนี้','อย่าตีความว่าเป็น Motor B ในทุกยี่ห้อ'],['P0A94<br>DC/DC Converter Performance','ชื่อ converter ต้องดูสถาปัตยกรรม; ใน Toyota อาจเกี่ยวกับชุด boost','ไม่อนุมัติเปลี่ยน DC-DC 12 V จากชื่อรหัสอย่างเดียว'],['P0A1A / P324E / P3004<br>รหัสร่วมในเอกสาร Toyota','เอกสาร J0V และ 23TE03 ระบุชุดรหัสสำหรับตรวจบริบท Inverter/IPM','ชื่อรหัสและวิธีทดสอบต้องเปิดคู่มือรถ ไม่ขยายความรหัสผู้ผลิตเอง']])+steps(['ยืนยัน VIN และรหัสย่อยก่อนเทียบ recall/TSB','ตรวจ LV การสื่อสาร อุณหภูมิ และความพร้อม HV จากข้อมูล','หากเกี่ยวข้องภาคกำลัง ให้ใช้ขั้นตอนและผู้ชำนาญที่กำหนด'])+note('IPM (Intelligent Power Module) คือโมดูลกำลังรวมฟังก์ชันบางส่วน กลุ่มรหัสนี้มีหลักฐานในงานบริการ แต่ไม่ใช่อัตราความถี่ของ BEV ไทย'),['S6','S7']);
add('08 / DTC','P0D26 และรหัสร่วมที่ต้องเปิดคู่มือ GM','GM S5: HPCM2; Volt 2011–2015, ELR 2014–2016, Ampera 2011–2014, Holden Volt 2013–2014',table(dtcHead,[['P0D26<br>Mitsubishi 2022 PHEV: charger system (precharge)','คู่มือผู้ผลิตอธิบายการติดตามแรงดันตัวเก็บประจุช่วงเริ่มชาร์จ','อ่านขั้นตอนตรงรุ่น; ไม่ใช้เกณฑ์แรงดันของรุ่นนี้กับรถอื่น'],['P1FFF<br>รหัสผู้ผลิต GM ใน S5','อยู่ในบริบทชาร์จไม่ได้/ฉนวนและการจัดการความผิดปกติ','ใช้คำจำกัดความจากคู่มือ GM ปีและกล่องที่ตรงรถ'],['P1F0E<br>รหัสผู้ผลิต GM ใน S5','พบในกลุ่มรถและปีที่ bulletin กำหนด','ไม่ลบรหัสหรือ reset โดยข้ามการวิเคราะห์'],['P0DAA<br>รหัสในบริบท GM S5','ต้องดูรุ่น ปี และกล่องผู้รายงานตาม bulletin','ไม่สรุปว่าเป็น OBC เสียจากรหัสนี้เพียงตัวเดียว']])+checks([['ก่อนเริ่มทดสอบ','ตรวจปลั๊ก/ล็อก/permission จากข้อมูล','รถน้ำท่วมต้องผ่านคัดกรองก่อน'],['ระหว่างตรวจ','เทียบรถกับสถานีและเงื่อนไขอุณหภูมิ','บันทึกว่า AC หรือ DC'],['หลังซ่อม','ทวนสอบตามขั้นตอนที่อนุญาตและเก็บ log','การลบรหัสสำเร็จไม่ยืนยันซ่อมครบ']])+note('ไม่ได้แปลความหมายรหัส P1xxx ข้ามยี่ห้อ ตารางนี้ระบุขอบเขตหลักฐานแทนการสร้างนิยามที่ไม่มีแหล่งยืนยัน'),['S5','S11']);
add('08 / DTC','U0100 / U0101 / U0111: กล่องไม่สื่อสาร','ตัวอย่าง S14: 2022 Wagoneer 5.7L eTorque แบบ MHEV (mild hybrid: ไฮบริดเสริมกำลัง)',table(dtcHead,[['U0100<br>Lost communication with ECM/PCM A','บางกล่องไม่พบการสื่อสารจากกล่องเครื่องยนต์/ระบบส่งกำลัง','ใน BEV ต้องตรวจชื่อปลายทางจาก OEM ไม่สมมติว่ามี ECM แบบเครื่องยนต์'],['U0101<br>Lost communication with TCM','ขาดการสื่อสารกล่องระบบส่งกำลังตามสถาปัตยกรรม','ตรวจ topology และไฟร่วม ไม่สรุป TCM เสีย'],['U0111<br>Lost communication with battery energy control module','กล่องผู้รายงานไม่ได้รับข้อมูลจากโมดูลแบตเตอรี่','ดู LV/Wake ของ BMS, Gateway และบัสที่เกี่ยวข้อง'],['หลาย U-code พร้อมกัน','พบได้เมื่อกล่องร่วม/แหล่งจ่ายร่วมผิดปกติ','เรียงเวลารหัสกับแรงดัน LV ก่อนเปลี่ยนหลายกล่อง']])+steps(['ทำตารางว่า ECU ใดเป็นผู้รายงาน และ ECU ใดเป็นเป้าหมายที่หาย','ดูว่าหายทั้งเครือข่ายหรือเฉพาะกิ่ง','ซ่อมจุดร่วม แล้วตรวจกล่องทั้งหมดอีกครั้ง'])+note('ECM/PCM คือกล่องเครื่องยนต์/ชุดส่งกำลัง; TCM คือกล่องควบคุมเกียร์ ชื่อและบทบาทจริงขึ้นกับรถ บันทึก S14 มาจาก MHEV ไม่ใช่ BEV/PHEV ใช้ยืนยันการบันทึกรหัส ไม่ใช่ความถี่หรือขั้นตอนวินิจฉัย BEV'),['S14']);
add('08 / DTC','U0401 / U0422 และข้อมูลไม่น่าเชื่อถือ','Invalid data ต่างจาก lost communication',table(dtcHead,[['U0401<br>Invalid data received from ECM/PCM A','อาจได้รับข้อความแล้วแต่ข้อมูลหรือสถานะไม่ผ่านการตรวจสอบ','ดู source ECU, DTC ต้นทาง software และการตั้งค่า'],['U0422<br>Invalid data received from BCM','เกี่ยวข้องกับข้อมูลจากกล่องควบคุมตัวถังในรถที่ใช้รหัสนี้','ตรวจไฟ/กราวด์และ DTC ของ BCM ก่อน'],['รหัสพร้อมแรงดันต่ำ','กล่องรีเซตหรือเริ่มระบบคนละเวลาอาจเกี่ยวข้อง','ยืนยันจากเวลาและข้อมูล ไม่ใช่สันนิษฐานจากรหัส'],['รหัสหลังซ่อมหรือเปลี่ยนกล่อง','ต้องดู variant coding และ compatibility','อย่าลงซอฟต์แวร์โดยเดาหรือข้ามขั้นตอน OEM']])+checks([['มีรูปคลื่น CAN','ยืนยันเพียงกิจกรรมทางกายภาพ','ไม่ยืนยันข้อมูล application ถูกต้อง'],['รหัส history เท่านั้น','บันทึกก่อนลบตามแผน','ทดสอบเกิดซ้ำอย่างปลอดภัยและมีเงื่อนไข'],['หลายระบบเตือนตามกัน','หา first fault และแหล่งข้อมูลร่วม','รหัสตามหลังไม่จำเป็นต้องซ่อมทุกกล่อง']])+note('BCM (Body Control Module) คือกล่องควบคุมตัวถัง ความหมายรหัสและ suffix ที่เครื่องสแกนแสดงต้องเทียบฐานข้อมูล OEM'),['S14']);
add('08 / DTC','ตารางสัมพันธ์ DTC กับอาการหลังน้ำท่วม','เป็นความเป็นไปได้เชิงวินิจฉัย ไม่ใช่รายการรหัสเฉพาะน้ำท่วม',table(['กลุ่มรหัส / อาการ','หลักฐานทางกายภาพที่ต้องหา','การดำเนินการ'],[['P0AA6 / ค่า isolation ผิด','ประวัติน้ำ แพ็ก/สาย HV/อุปกรณ์เสียหายหรือของเหลวรั่ว','หยุด READY/ชาร์จ; ตรวจด้วยขั้นตอนฉนวนเฉพาะรุ่น'],['U0100 / U0101 / U0111','คราบที่ปลั๊ก/สายร่วม/ฟิวส์/กราวด์; เวลาไฟ LV ตก','ประเมิน HV ก่อน แล้วตรวจ LV/เครือข่ายตามผัง'],['U0401 / U0422','ความผิดปกติข้อมูลต้นทางและคราบที่วงจรต้นทาง','อ่าน source ECU ก่อนตัดสินเครือข่าย'],['วงจรเซนเซอร์ open/short<br>ใช้รหัสตรง OEM','คราบขั้ว ความชื้น ซีลฉีก สายชำรุด','ยืนยันขาและพิกัดก่อนตรวจ ไม่มีรหัสกลางที่เหมาทุกเซนเซอร์'],['ชาร์จไม่ได้ / รหัส OBC','น้ำที่พอร์ต/สาย/ชุดชาร์จ และข้อจำกัดจาก BMS','ไม่ทดลองเสียบชาร์จเพื่อไล่หาอาการ']])+note('รถน้ำท่วมอาจไม่มีรหัสเลย และรหัสเหล่านี้อาจเกิดในรถที่ไม่เคยน้ำท่วม ห้ามออกใบรับรองประวัติน้ำท่วมจาก DTC เพียงอย่างเดียว')+steps(['บันทึกชนิดน้ำ ระดับน้ำ ระยะเวลาจม และสิ่งที่เจ้าของได้ทดลองแล้ว','เก็บภาพหลักฐานโดยไม่รื้อส่วน HV ที่ยังไม่ปลอดภัย','ผูกหลักฐานแต่ละชิ้นกับอาการและวิธีตรวจที่ทำจริง']),['S8','S9','S14']);
add('08 / DTC','ใบคัดกรองและเกณฑ์ส่งต่อรถน้ำท่วม','ไฟเตือนดับแล้ว ยังต้องยืนยันความปลอดภัยและคุณภาพงาน',table(['หัวข้อรับรถ','บันทึก','การตัดสินใจ'],[['น้ำจืด / กร่อย / เค็ม / ไม่ทราบ','ชนิด ____ ระดับ ____ ระยะเวลา ____','ไม่ทราบให้ระบุไม่ทราบ ไม่เดาจากคราบ'],['แพ็ก / สาย HV / ใต้ท้อง','เสียหาย ____ ภาพอ้างอิง ____','สงสัยน้ำเข้า/เสียหาย → ส่งผู้ชำนาญ'],['อาการร้อน/ควัน/กลิ่น/เสียง','เวลา ____ จุดสังเกต ____','หยุดงาน ออกจากพื้นที่ แจ้งผู้ตอบเหตุ'],['การทดลองก่อนรับรถ','READY ____ ชาร์จ ____ jump start ____','บันทึกเป็นประวัติ ไม่ทำซ้ำเพื่อยืนยัน'],['ขอบเขตตรวจที่อนุมัติ','เอกสาร OEM ____ ผู้รับผิดชอบ ____','ไม่ทำ HV ถ้าเครื่องมือ/ทักษะ/ข้อมูลไม่พร้อม']])+table(['ก่อนส่งคืนหลังการซ่อมโดยผู้มีคุณสมบัติ','หลักฐาน'],[['ผลฉนวนและเงื่อนไขทดสอบตาม OEM','เลขขั้นตอน/เกณฑ์/ผลจริง/ผู้ทดสอบ'],['DTC ทุกกล่องและเงื่อนไขทวนสอบ','รายงานก่อน–หลัง พร้อม suffix'],['หัวต่อ ซีล และชิ้นส่วนที่ซ่อม/เปลี่ยน','รูปภาพ รายการอะไหล่ และ torque ตาม OEM'],['ข้อจำกัดและการติดตามตามแผนบริการ','ระบุรายการที่ยังไม่ตรวจ ห้ามใช้คำว่าปลอดภัยเพียงเพราะไม่มีรหัส']])+note('ไม่เปิดแพ็ก ล้างวงจร หรือชาร์จเพื่อพิสูจน์ความเสียหายระหว่างคัดกรอง รถน้ำท่วมมีความเสี่ยงล่าช้าแม้ภายนอกแห้งแล้ว',true),['S8','S9','S15']);

add('09 / กรณีศึกษา','กรณี 1: P0A80/P0A7F กับทางลมแบตเตอรี่','กรณีอิงเอกสารบริการ; ไม่ใช่รายงานซ่อมรถที่ผู้จัดทำวัดเอง',fig(['MIL + codes|save data','Confirm vehicle|TSB applicability','Cooling path|inspect per OEM','Repair / confirm|OEM procedure'],'ลำดับคิดจากหลักฐาน ไม่สร้างผลวัดประกอบ')+table(['ขั้น','สิ่งที่ทราบ / สิ่งที่ต้องตรวจ','ผลต่อแผน'],[['หลักฐานจริง','Toyota T-SB-0049-14 Rev1 ครอบคลุม Camry HV 2013–2014 สหรัฐฯ ตามเงื่อนไข','ยืนยัน VIN และ revision ก่อน'],['กลไกที่เอกสารระบุ','ฝุ่น/เศษสิ่งสกปรกในพัดลมหรือทางลมแบตเตอรี่สัมพันธ์กับรหัส','ตรวจการระบายความร้อนเป็นส่วนหนึ่งของแผน'],['ข้อมูลที่ต้องเก็บจากรถ','block voltage, temp, current, SOC, fan; ยังไม่มีค่าจริงในกรณีนี้','ห้ามสร้างตัวเลขให้ดูเหมือนวัดจริง'],['ข้อสรุปที่ทำได้','ไม่ควรอนุมัติเปลี่ยนแพ็กจากรหัสเพียงตัวเดียว','เมื่อตรงเงื่อนไข TSB แนวซ่อมรวมจัดการพัดลม/ไส้กรองและเปลี่ยน HV Battery Assembly ตามคู่มือ VIN']])+note('จุดฝึก: เอกสารหนึ่งฉบับยืนยันความเป็นไปได้เฉพาะกลุ่มรถ ไม่ยืนยันว่าทุกรถที่มีรหัสนี้เสียด้วยสาเหตุเดียวกัน')+field(),['S4']);
add('09 / กรณีศึกษา','กรณี 2: Volt ชาร์จไม่ได้กับ P0AA6','อิง GM 21-NA-224; จำกัดรุ่น/ปีตามเอกสาร',fig(['No charge|DTC + freeze frame','Isolation data|record value','OEM diagnosis|coolant / pack','Repair + verify|authorized steps'],'อ่านค่าที่รถรายงานก่อนตรวจระบบฉนวนเชิงลึก')+table(['หลักฐาน / สมมติฐาน','วิธีพิสูจน์','ข้อจำกัด'],[['เอกสารครอบคลุม Volt 2011–2015 และรถร่วมแพลตฟอร์มบางปี','ตรวจตารางรุ่น/ปีในเอกสารต้นทาง','ไม่ใช้กับ Bolt หรือ EV ทุกยี่ห้อ'],['อาการชาร์จไม่ได้ร่วมรหัสกลุ่มฉนวน','อ่านกล่องผู้รายงานและข้อมูลฉนวนในรายการสแกน','ชื่อ PID ต้องตรงระบบและเครื่องมือ'],['เอกสารระบุ coolant loss และการสูญเสียฉนวนเป็นสาเหตุที่ต้องพิจารณา','ให้ผู้ชำนาญทำขั้นตอนแยกสาเหตุตาม OEM','ไม่สรุปว่าโดนน้ำท่วมเพราะมี P0AA6'],['ผลซ่อมจริงในกรณีนี้','ยังไม่มีรถหรือผลวัดจริงให้ยืนยัน','เป็นกรณีศึกษาเอกสาร ไม่อ้างซ่อมสำเร็จ']])+note('จุดฝึก: แยกน้ำจากภายนอกกับน้ำหล่อเย็นในระบบ รหัสเหมือนกันอาจมีต้นเหตุและวิธีซ่อมต่างกัน',true)+field(),['S5']);
add('09 / กรณีศึกษา','กรณี 3: หลาย U-code กับไฟ LV ร่วม','สถานการณ์ฝึกสมมติ ไม่มีตัวเลขอ้างว่าเป็นผลวัดจริง',fig(['Several U-codes|scan all ECUs','Shared LV?|compare timing','Voltage drop|LV only','Repair joint|verify network'],'ตรวจจุดร่วมก่อนเปลี่ยนกล่องหลายตัว')+table(['ข้อสังเกตสมมติ','แผนตรวจ','จะสรุปเมื่อใด'],[['หลายกล่องเก็บ U0111 และบางกล่องรีเซต','เก็บ topology กับแรงดัน LV ขณะเกิดเหตุ','หากพบสัมพันธ์เวลา ค่อยตั้งสมมติฐานแหล่งจ่าย'],['แบตเตอรี่ LV ที่ขั้วดูปกติ','วัดไฟถึงกล่องและ voltage drop ฝั่งกราวด์ขณะโหลด','พบตกคร่อมจริงและแยกจุดต่อได้'],['สงสัยขั้วร่วมกัดกร่อน','ทำให้ปลอดไฟก่อนเปิดตรวจตาม OEM','มีหลักฐานภาพและการวัดรองรับ'],['หลังแก้จุดต่อ','คืนระบบตามขั้นตอน สแกนและทำเงื่อนไขเดิมที่ปลอดภัย','การสื่อสารและไฟเลี้ยงกลับมาปกติตามเกณฑ์จริง']])+note('จุดฝึก: U-code บอกความสัมพันธ์ผู้รายงานกับผู้ถูกอ้างถึง ไม่ระบุชิ้นส่วนเสียโดยตรง หากไม่พบการตกคร่อม ต้องเปลี่ยนสมมติฐาน ไม่แต่งผลให้ตรงแผน')+field(),['S14']);
add('09 / กรณีศึกษา','กรณี 4: รถน้ำท่วม สแกนไม่พบรหัส','สถานการณ์ฝึก: ยอมรับข้อจำกัดและหยุดก่อนทำให้เสี่ยงเพิ่ม',fig(['Flood history|unknown depth','No DTC|not proof of safety','HV specialist|OEM assessment','Document limits|no forced READY'],'เกณฑ์ส่งต่อสำคัญกว่าการทดลองเปิดระบบ')+table(['ข้อมูลรับรถสมมติ','ตัดสินใจ','เหตุผล'],[['รถแห้งภายนอก เจ้าของบอกเคยจมน้ำ','ไม่ชาร์จหรือเปิด READY เพื่อทดสอบ','คราบนำไฟและความเสียหายซ่อนอยู่ได้'],['เครื่องมืออ่านแล้วไม่มี DTC หรือบางกล่องไม่ตอบ','บันทึกข้อจำกัด สภาพระบบ และรายชื่อกล่อง','การตรวจอาจยังไม่เข้าเงื่อนไขหรือกล่องไม่ตื่น'],['ไม่ทราบชนิดน้ำ/ระดับน้ำถึงแพ็กหรือไม่','ระบุไม่ทราบ ส่งผู้เชี่ยวชาญประเมินตามรุ่น','ไม่ใช้การคาดเดารับรองความปลอดภัย'],['ต้องออกรายงานให้เจ้าของ','ระบุสิ่งที่ตรวจ สิ่งที่ยังไม่ตรวจ และผู้รับงานต่อ','ไม่มีรหัสไม่เท่ากับไม่มีความเสี่ยง']])+note('จุดฝึก: ถ้าเริ่มร้อน มีควันหรือเสียงผิดปกติระหว่างรอ ให้หยุด ออกห่าง และแจ้งผู้ตอบเหตุ ไม่รอผลสแกนและไม่พยายามเปิดแพ็ก',true)+field(),['S8','S9']);

add('10 / อ้างอิง','ตารางหน่วย ค่าตัวอย่าง และข้อห้ามใช้เหมารวม','ใช้ค้นเร็ว ก่อนกลับไปอ่านเกณฑ์ OEM',table(['หัวข้อ','ค่าหรือหลักการอ้างอิง','ขอบเขต / แหล่ง'],[['CAN termination','120 Ω สองตัวขนาน = 60 Ω','ตัวอย่าง HS-CAN บัสปลอดไฟ ไม่มีวงจรอื่นรบกวน; S2'],['CAN แรงดันตัวอย่าง','Recessive ~2.5 V; Dominant H ~3.5 / L ~1.5 V','ตัวอย่าง transceiver 5 V; ไม่ใช่ค่าตัดสินทุกระบบ; S2'],['ΔV ของช่องแบตเตอรี่','V สูงสุด − V ต่ำสุด ในข้อมูลเวลาเดียวกัน','เกณฑ์ผ่านขึ้นกับ SOC โหลด เคมี อุณหภูมิ OEM'],['Power / Energy','W = V×A (DC ตามเงื่อนไข); Wh = พลังงาน','kW เป็นกำลัง ไม่ใช่ความจุ; kWh เป็นพลังงาน'],['Voltage drop','วัดคร่อมช่วงสายขณะมีโหลดที่ทราบ','ไม่ใช้เลขเกณฑ์เดียวกับทุกวงจร'],['HV discharge time / torque / pinout','ไม่มีค่าครอบจักรวาลในเล่มนี้','ใช้คู่มือเฉพาะ VIN และ revision'],['Insulation test','จุดแยก แรงดันทดสอบ และเกณฑ์ผ่านจาก OEM เท่านั้น','ไม่ใช้ megohmmeter กับวงจรที่ยังเชื่อมโดยเดา'],['รหัสหลังน้ำท่วม','ไม่มี DTC ตัวเดียวรับรองประวัติน้ำท่วมหรือความปลอดภัย','ใช้ประวัติ หลักฐานกายภาพและการตรวจที่ถูกต้อง']])+table(['เครื่องมือ','บันทึกก่อนใช้'],[['DMM (มัลติมิเตอร์ดิจิทัล)','พิกัดแรงดัน/หมวดการวัด/สายวัด/การทวนสอบที่เหมาะกับงาน'],['Scan tool','รุ่นโปรแกรม/ฐานข้อมูล/กล่องที่รองรับ/รายการที่อ่านไม่ได้'],['Oscilloscope / Probe','พิกัด differential และ common-mode/การต่อกราวด์/ช่วงเวลา'],['ฉนวนและ HV','เฉพาะผู้ผ่านการฝึก ใช้จุด/เครื่องมือ OEM และทวนสอบเครื่องมือก่อน–หลังพิสูจน์ปลอดไฟ พร้อมแผนฉุกเฉิน']]),['S1','S2']);
add('10 / อ้างอิง','แหล่งข้อมูลและบัญชีสิทธิ์ภาพ','ลิงก์คลิกได้ในไฟล์ PDF • ดูทะเบียนฉบับเต็มในไฟล์ประกอบ',`<div class="sources">${Object.entries(S).map(([id,v])=>`<p><b>${id}</b> <a href="${v[1]}">${v[0]}</a></p>`).join('')}</div>`+table(['ภาพ / แหล่ง','สิทธิ์และการจัดการ'],[['ภาพ B ทุกหน้า','ภาพวาดใหม่โดยผู้จัดทำเพื่อเล่มนี้ • CC BY 4.0 • ไม่อ้างเป็นผัง OEM'],['ภาพ A หน้า 32 / ภาพ C หน้า 33','Adafruit Industries • A: CC BY-SA 2.5 ตามกรอบภาพ / C: CC BY-SA 3.0 ตาม repository; คงเครดิตและใบอนุญาตใน assets'],['กรอบรอภาพ A/C','ยังไม่ได้รับสิทธิ์หรือยืนยันภาพตามรุ่น จึงไม่ใช้แทนหลักฐานจริง'],['เอกสาร OEM/TSB/datasheet','ใช้สรุปและลิงก์อ้างอิง ไม่คัดลอกภาพที่ยังไม่มีสิทธิ์; เผยแพร่สาธารณะไม่เท่ากับอนุญาตใช้ซ้ำ']])+note('สถานะเล่ม: ต้นฉบับเพื่อการศึกษา ต้องมีผู้เชี่ยวชาญตรวจทานก่อนใช้สอนหรือออกเผยแพร่เชิงพาณิชย์ โดยเฉพาะขั้นตอน HV ความถูกต้อง DTC ตามรุ่น และภาพ OEM ที่ยังรอจัดหา'));

