const css=`@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#dce4e8;color:#183246;font-family:Tahoma,'Leelawadee UI',sans-serif;font-size:13.5px;line-height:1.65}.page{width:210mm;height:297mm;padding:13mm 14mm 15mm;background:white;position:relative;page-break-after:always;break-after:page;overflow:hidden}.page:last-child{page-break-after:auto;break-after:auto}.top{font-size:10px;letter-spacing:1px;color:#167f86;border-bottom:2px solid #167f86;padding-bottom:7px;margin-bottom:15px}h1{font-size:27px;line-height:1.35;margin:0 0 8px;letter-spacing:-.5px}h2{font-size:17px;margin:15px 0 8px}.sub{font-size:13px;color:#607887;margin-bottom:16px}table{border-collapse:collapse;width:100%;margin:13px 0 15px;table-layout:fixed;font-size:13.5px}th{background:#173b4a;color:white;text-align:left;padding:10px 11px;font-weight:normal}td{vertical-align:top;padding:10px 11px;border-bottom:1px solid #d5e1e6;overflow-wrap:anywhere}tr:nth-child(even) td{background:#f0f6f7}th:first-child,td:first-child{width:27%}aside{padding:13px 15px;border-left:4px solid #168087;background:#eaf5f5;margin:15px 0;font-size:13px}.warning{border-color:#d56b25;background:#fff2e5}.steps{margin:13px 0}.steps>div{display:flex;gap:11px;padding:9px 8px;border-bottom:1px solid #d9e4e9}.steps b{background:#167f86;color:white;border-radius:50%;min-width:23px;height:23px;text-align:center}.steps span{flex:1}figure{margin:14px 0;background:#f7fafb;border:1px solid #d9e7ea;padding:11px}figure svg{width:100%;height:200px;display:block}figcaption{font-size:10px;line-height:1.6;margin-top:7px;color:#58717f}figcaption b{color:#167f86}.actual img{width:100%;height:345px;object-fit:contain;background:white}.photo img{width:100%;height:300px;object-fit:contain;background:white}.slot{border:1px dashed #a1afb5;background:#f6f7f8;padding:24px 20px;margin:15px 0;color:#6b7981;text-align:center;min-height:132px}.slot small{font-size:10px}.refs{font-size:9px;color:#647b86;margin-top:14px;line-height:1.6}a{color:#167f86;text-decoration:none}.foot{position:absolute;bottom:8mm;left:14mm;right:14mm;border-top:1px solid #ccdbe0;padding-top:5px;display:flex;justify-content:space-between;font-size:9px;color:#5a737f}.field{padding:12px;border:1px solid #bccfd6;margin-top:15px;font-size:10px;line-height:2.1}.coverline{font-size:16px;color:#167f86;margin:30px 0}.coverbadge{font-size:22px;line-height:1.6;margin:35px 0 20px}.page:first-child h1{font-size:47px;line-height:1.2;letter-spacing:-2px;margin:36px 0 20px}.page:first-child .sub{font-size:21px;color:#173b4a;line-height:1.6}.page:first-child figure svg{height:210px}.sources{display:grid;grid-template-columns:1fr 1fr;gap:0 18px;font-size:10px}.sources p{margin:4px 0;padding:4px 0;border-bottom:1px solid #e3ebef}.page:last-child table{font-size:10px}.page:last-child td,.page:last-child th{padding:7px 9px}@media screen{.page{margin:16px auto;box-shadow:0 4px 15px #a7b7bf}}@media print{body{background:white}.page{margin:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}}`;
function render(p,i){return `<section class="page" id="page-${i+1}"><header class="top">EV CIRCUIT & DTC HANDBOOK <span style="float:right">${p.section}</span></header><main><h1>${p.title}</h1><div class="sub">${p.sub}</div>${p.body}${p.ids.length?refs(p.ids):''}</main><footer class="foot"><span>คู่มือช่าง EV • ต้นฉบับเพื่อการศึกษา • 9 พ.ย. 2569</span><b>${String(i+1).padStart(2,'0')} / 50</b></footer></section>`}
const html=`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>EV CIRCUIT & DTC HANDBOOK</title><style>${css}${realLayout.css}</style></head><body>${P.map(render).join('\n')}</body></html>`;
fs.writeFileSync('EV-CIRCUIT-DTC-HANDBOOK.html',html);
